void list_push_front(node_t **head, int data) {
    if (!head) return;
    node_t *n = malloc(sizeof *n);
    if (!n) return;
    n->data = data;
    n->next = *head;
    *head = n;
}

void list_push_back(node_t **head, int data) {
    if (!head) return;
    node_t *n = malloc(sizeof *n);
    if (!n) return;
    n->data = data; n->next = NULL;
    node_t **pp = head;
    while (*pp) pp = &(*pp)->next;
    *pp = n;
}

bool list_delete_value(node_t **head, int value) {
    if (!head) return false;
    node_t **pp = head;
    while (*pp) {
        if ((*pp)->data == value) {
            node_t *dead = *pp;
            *pp = dead->next;
            free(dead);
            return true;
        }
        pp = &(*pp)->next;
    }
    return false;
}

void list_reverse(node_t **head) {
    if (!head) return;
    node_t *prev = NULL, *cur = *head;
    while (cur) {
        node_t *nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    *head = prev;
}

node_t *list_find_middle(node_t *head) {
    node_t *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

bool list_has_cycle(node_t *head) {
    node_t *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

node_t *list_merge_sorted(node_t *a, node_t *b) {
    node_t dummy; dummy.next = NULL;
    node_t *tail = &dummy;
    while (a && b) {
        if (a->data <= b->data) { tail->next = a; a = a->next; }
        else                    { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

node_t *list_nth_from_end(node_t *head, size_t n) {
    if (n == 0) return NULL;
    node_t *lead = head;
    for (size_t i = 0; i < n; ++i) {
        if (!lead) return NULL;
        lead = lead->next;
    }
    node_t *trail = head;
    while (lead) { lead = lead->next; trail = trail->next; }
    return trail;
}

bool dlist_delete_value(dnode_t **head, int value) {
    if (!head) return false;
    dnode_t *cur = *head;
    while (cur && cur->data != value) cur = cur->next;
    if (!cur) return false;
    if (cur->prev) cur->prev->next = cur->next;
    else           *head = cur->next;
    if (cur->next) cur->next->prev = cur->prev;
    free(cur);
    return true;
}

void dlist_reverse(dnode_t **head) {
    if (!head) return;
    dnode_t *cur = *head, *newhead = *head;
    while (cur) {
        dnode_t *nxt = cur->next;
        cur->next = cur->prev;
        cur->prev = nxt;
        newhead = cur;
        cur = nxt;
    }
    *head = newhead;
}

#define POOL_SIZE 8
static pnode_t g_pool[POOL_SIZE];
static pnode_t *g_free_list = NULL;

void pool_init(void) {
    for (int i = 0; i < POOL_SIZE - 1; ++i) g_pool[i].next = &g_pool[i+1];
    g_pool[POOL_SIZE - 1].next = NULL;
    g_free_list = &g_pool[0];
}
pnode_t *pool_alloc(void) {
    if (!g_free_list) return NULL;
    pnode_t *n = g_free_list;
    g_free_list = n->next;
    n->next = NULL;
    return n;
}
void pool_free(pnode_t *n) {
    if (!n) return;
    n->next = g_free_list;
    g_free_list = n;
}
bool pool_push_front(pnode_t **head, int data) {
    if (!head) return false;
    pnode_t *n = pool_alloc();
    if (!n) return false;
    n->data = data; n->next = *head; *head = n;
    return true;
}
